task.update(statement='Lin An opens the letter before leaving the stage.',answer=False,
            why='She puts the letter in her bag and leaves without opening it.')
questions=pack['extraReadings'][-1]['questions']
questions[0].update(q='What does the musician describe?',
                    choices=['How the song and stage movements are rehearsed',
                             'The complete text of the unopened letter',
                             'A confirmed date for next week’s show'],
                    answer='How the song and stage movements are rehearsed')
questions[1].update(choices=['Read full lines and phrase them clearly',
                            'Move the last line to the opening',
                            'Replace the song with spoken dialogue'])
target.write_text(json.dumps(pack,ensure_ascii=False,indent=2)+'\n','utf-8')
